-- engine/hold_fuel.lua
-- The HOLD-side econ channel (mirror of engine/discard_fuel, which is the discard side). Expected
-- in-blind $ generated by the cards you HOLD in hand at scoring -- the money the engine earns by
-- playing a MINIMAL hand and keeping econ cards back, rather than dumping them into the winner. PURE.
--
-- Reserved Parking is VALUE_ONLY in joker_effects (hand_eval never computed its per-hand held money),
-- so without this the engine had no way to see that "play a single high card, hold a hand of faces"
-- earns money -- MILK only ever valued PLAYED-card money.
--
-- Levers:
--   Reserved Parking  +$1 per held FACE card, at a 1/2 chance (-> $0.5 expected; Oops! All 6s doubles
--                      the odds to a certainty).  -- VERIFY prob (wiki 1/2).
--   Gold card (m_gold) +$3 per held gold card at round end -- preserved by NOT playing it.

local Cards    = require("util.cards")
local HandEval = require("engine.hand_eval")

local HF = {}

local function owns(gs, key)
  for _, j in ipairs(gs.jokers or {}) do if j.key == key then return true end end
  return false
end

-- Expected $ from HOLDING `held` cards this hand. (A debuffed card counts for nothing.)
function HF.money(gs, held)
  if not held or #held == 0 then return 0 end
  local d = 0
  if owns(gs, "j_reserved_parking") then
    local prob = owns(gs, "j_oops") and 1.0 or 0.5              -- Oops doubles the 1/2 chance
    for _, c in ipairs(held) do
      if Cards.is_face(c) and not HandEval.is_debuffed(gs, c) then d = d + prob end
    end
  end
  for _, c in ipairs(held) do
    if c.enhancement == "m_gold" and not HandEval.is_debuffed(gs, c) then d = d + 3 end  -- $3 held at round end
  end
  return d
end

-- Does the player own a HOLD lever worth playing minimally to farm? (m_gold is per-card, handled by the
-- per-hand HF.money above; the lever gate is for the joker that makes holding faces pay.)
function HF.has_lever(gs)
  return owns(gs, "j_reserved_parking")
end

return HF
